mod tests {
    use super::*;

    #[test]
    fn composer_retirement_cli_requires_exact_workspace_and_fresh_output() {
        for argv in [
            vec!["droidloom-update", "composer-retirement-build"],
            vec!["droidloom-update", "composer-retirement-build", "--work", "/not-executed"],
            vec!["droidloom-update", "composer-retirement-build", "--out", "/not-executed"],
            vec!["droidloom-update", "composer-retirement-build", "--work", "/not-executed",
                 "--out", "/not-executed/out", "services"],
            vec!["droidloom-update", "composer-retirement-build", "--work", "/not-executed",
                 "--out", "/not-executed/out", "--tests"],
            vec!["droidloom-update", "composer-retirement-build", "--work", "/not-executed",
                 "--out", "/not-executed/out", "--resume-source-staging", "/not-executed/partial"],
        ] {
            assert!(Args::try_parse_from(argv).is_err());
        }
        let temp = tempfile::tempdir().unwrap();
        let work = temp.path();
        let out = work.join("composer-out");
        let parse = |path: &std::path::Path| Args::try_parse_from([
            "droidloom-update", "composer-retirement-build",
            "--work", work.to_str().unwrap(), "--out", path.to_str().unwrap(),
        ]).unwrap();
        let args = parse(&out);
        assert!(matches!(args.command, Some(Action::ComposerRetirementBuild { .. })));
        assert_eq!(selected_build_out(args.command.as_ref(), work).unwrap(), out);
        for path in [work.to_owned(), work.join("aosp-source"), work.join("aosp-source/out")] {
            assert!(selected_build_out(parse(&path).command.as_ref(), work).is_err());
        }
        fs::create_dir(&out).unwrap();
        assert!(selected_build_out(parse(&out).command.as_ref(), work).is_err());
        let alias = work.join("alias");
        std::os::unix::fs::symlink(work, &alias).unwrap();
        assert!(selected_build_out(parse(&alias.join("new")).command.as_ref(), work).is_err());
        assert!(!work.join("package-build.lock").exists());
        assert!(!work.join("aosp-source-update.lock").exists());
        assert!(!work.join("source-projection.json").exists());
    }
